<script lang="ts">import { enhance } from '$app/forms';let {data,form}=$props();</script><svelte:head><title>Persetujuan Pengajuan</title></svelte:head><div class="wrap"><h2>Persetujuan Pengajuan Akses</h2><p>Tinjau role dan sekolah sebelum akses aktif. Persetujuan meminta pengguna masuk kembali agar role pada sesi diperbarui.</p>{#if form?.error}<p class="error">{form.error}</p>{/if}{#if data.requests.length===0}<p>Tidak ada pengajuan pending.</p>{:else}{#each data.requests as r}<article><h3>{r.requesterName} <small>{r.requesterEmail}</small></h3><p><strong>{r.requestedRole}</strong>{#if r.schoolName} · {r.schoolName}{/if}</p>{#if r.note}<p>{r.note}</p>{/if}<form method="POST" action="?/approve" use:enhance><input type="hidden" name="id" value={r.id}/><input name="note" placeholder="Catatan persetujuan (opsional)"/><button>Setujui</button></form><form method="POST" action="?/reject" use:enhance><input type="hidden" name="id" value={r.id}/><input name="note" placeholder="Alasan penolakan"/><button class="reject">Tolak</button></form></article>{/each}{/if}</div><style>.wrap{display:grid;gap:1rem}.wrap>p{color:var(--lp-ink-2)}article{border:1px solid var(--lp-rule);border-radius:.8rem;padding:1rem;background:#fff}h3{margin:0}small{font-weight:400;color:var(--lp-ink-2)}form{display:flex;gap:.5rem;margin-top:.55rem}input{flex:1;padding:.5rem;border:1px solid var(--lp-rule);border-radius:.45rem}button{border:0;background:var(--lp-accent-deep);color:white;border-radius:.45rem;padding:.5rem .75rem}.reject{background:#9f1239}.error{color:#b42318}</style>
